using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation properties
        // or complex expressions – use fixed seed values only.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }

    // EF Core 9 Cosmos breaking change: The discriminator property is now named "$type"
    // by default instead of "Discriminator". For existing documents that use "Discriminator",
    // explicitly configure the old property name in OnModelCreating (see CosmosDbContext below).
}

// Cosmos DB context demonstrating required fixes for EF Core 9 breaking changes.
class CosmosDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Configure Cosmos DB provider as needed
        // optionsBuilder.UseCosmos("endpoint", "key", "database");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: Discriminator property renamed from "Discriminator" to "$type".
        // For existing documents, explicitly set the old name to avoid query mismatches.
        modelBuilder.Entity<Order>().HasDiscriminant("Discriminator");

        // Breaking change #2: Sync Cosmos queries removed in EF Core 9.
        // All queries must use async (ToListAsync, FirstOrDefaultAsync, etc.).
        // See CosmosQueryService below for the required migration pattern.
    }
}

// Breaking change #3: Synchronous Cosmos DB queries are no longer supported.
// EF Core 9 removes sync-over-async for the Cosmos provider.
// Before (throws InvalidOperationException in EF Core 9):
//   var orders = db.Orders.ToList();
// After (required fix):
//   var orders = await db.Orders.ToListAsync();
class CosmosQueryService
{
    // All Cosmos queries must be async in EF Core 9
    async Task<List<Order>> GetOrdersAsync(CosmosDbContext db)
    {
        return await db.Orders.ToListAsync();
    }
}

