using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "$type" instead
        // of "Discriminator" for the discriminator property by default.
        // For existing documents that already have "Discriminator", you must
        // explicitly configure the old property name to avoid data issues.
        modelBuilder.Entity<Vehicle>(b =>
        {
            b.ToContainer("Vehicles");
            b.HasDiscriminator<string>("Discriminator");
        });

        modelBuilder.Entity<Car>().HasBaseType<Vehicle>();
        modelBuilder.Entity<Truck>().HasBaseType<Vehicle>();
    }
}

// EF Core 9 breaking change: Synchronous I/O on Cosmos provider now throws by
// default. All queries/saves must use async methods (ToListAsync, SaveChangesAsync,
// etc.). If you absolutely need sync, opt in with:
//   options.UseCosmos(...).ConfigureWarnings(w => w.Ignore(CosmosEventId.SyncNotSupported));
// But strongly prefer converting to async as shown below.

