    //   var cars = db.Vehicles.OfType<Car>().ToList();
    //
    // AFTER (EF Core 9 — must use async):
    async Task<List<Car>> GetCarsAsync(CosmosDbContext db)
    {
        return await db.Vehicles.OfType<Car>().ToListAsync();
    }

    async Task SaveVehicleAsync(CosmosDbContext db, Vehicle vehicle)
    {
        db.Vehicles.Add(vehicle);
        await db.SaveChangesAsync();
    }
}

